      hu: "Sizuoka prefektúra a legnagyobb teatermelő Japánban. A lankás dombokat rendezett teasorok borítják, gyakran lenyűgöző kilátással a Fudzsi-hegyre a háttérben.",
      ro: "Prefectura Shizuoka este cel mai mare producător de ceai din Japonia. Dealurile sale domoale sunt acoperite de rânduri ordonate de tufe de ceai, adesea cu vederi uimitoare ale Muntelui Fuji în fundal.",
      en: "Shizuoka Prefecture is the largest producer of tea in Japan. Its rolling hills are covered with neat rows of tea bushes, often with stunning views of Mount Fuji in the background.",
      es: "La prefectura de Shizuoka es el mayor productor de té de Japón. Las suaves colinas están cubiertas de hileras ordenadas de arbustos de té y suelen ofrecer vistas impresionantes del monte Fuji.",
      pt: "A província de Shizuoka é o maior produtor de chá do Japão. As colinas suaves estão cobertas por fileiras ordenadas de arbustos de chá e oferecem frequentemente vistas deslumbrantes do Monte Fuji.",
