      de: ["Besucher können Delfine und Robben berühren.", "Kombiniert einen kleinen Vergnügungspark mit einem Aquarium.", "Ein beliebter Tagesausflug von Nagoya aus.", "Die Pinguin-Insel ist ein besonderes Highlight für Kinder."],
