      fr: ["Les visiteurs peuvent toucher les dauphins et les phoques.", "Combine un petit parc d'attractions avec un aquarium.", "Une excursion d'une journée populaire depuis Nagoya.", "L'île aux pingouins est un moment fort pour les enfants."],
